#include <stdio.h>

int main(void)
{
    int a = 4, b = 3, c = 6;
    int *p = &a;               /* 单目 &：取 a 的地址 */

    printf("%d\n", *p + b);      /* 单目 *：4 + 3 = 7 */
    printf("%d\n", a * b);       /* 双目 *：乘法 12 */
    printf("%d\n", a & b);       /* 双目 &：100 & 011 = 0 */
    printf("%d\n", *p * *(&b));  /* 混合：4 * 3 = 12 */
    printf("%d\n", *(&a));       /* 互逆：回到 a，4 */
    printf("%d\n", c & *p);      /* 6 & 4 = 4 */
    return 0;
}

