}

#include <stdio.h>

int main(void)
{
    int i = 2;
    float f = 1.5f;
    char c = 'A';
    double d = 3.0;

    printf("%g\n", i + f);            /* int+float → float，3.5 */
    printf("%g\n", i + d);            /* int+double → double，5 */
    printf("%d\n", i > f);            /* 关系表达式 → int，1 */
    printf("%d\n", c + 1);            /* char 提升为 int，66 */
    printf("%g\n", i > 1 ? f : d);    /* ?: 取公共类型 double，1.5 */
    printf("%d\n", (i = 9) + 1);      /* 赋值表达式类型是 int，9+1 = 10 */
    printf("%g\n", (double)i / 4);    /* 强制转换后是 double，2.25 */
    return 0;
}

